// ---- Circuit (Kit 5) ----
// L293D: pin 16 + EN -> logic 5V, pin 8 -> +6V pack, GND pins -> GND; EN1,2 <- D6 (PWM), 1A <- A1, 2A <- A2
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define L293_EN 6
#define L293_1A A1
#define L293_2A A2
#define BTN1 2

int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}
void motor293(int speed) {                  // -255 .. 255 ; EN1,2 carries the PWM
  if (speed > 0) { digitalWrite(L293_1A, HIGH); digitalWrite(L293_2A, LOW); }
  else if (speed < 0) { digitalWrite(L293_1A, LOW); digitalWrite(L293_2A, HIGH); }
  else { digitalWrite(L293_1A, LOW); digitalWrite(L293_2A, LOW); }
  analogWrite(L293_EN, abs(speed));
}
void l293Begin() {
  pinMode(L293_EN, OUTPUT); pinMode(L293_1A, OUTPUT); pinMode(L293_2A, OUTPUT);
  motor293(0);
}

int state = 3;                               // start in COAST

void apply() {
  if (state == 0) { Serial.println("FORWARD"); motor293(255); }
  if (state == 1) { Serial.println("BRAKE (both outputs low, enable high)"); digitalWrite(L293_1A, LOW); digitalWrite(L293_2A, LOW); digitalWrite(L293_EN, HIGH); }
  if (state == 2) { Serial.println("REVERSE"); motor293(-255); }
  if (state == 3) { Serial.println("COAST (enable low)"); motor293(0); }
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  l293Begin();
  Serial.begin(9600);
  Serial.println("press the button to change state");
}

void loop() {
  if (pressed()) {
    state = (state + 1) % 4;
    apply();
  }
}

// ---- Circuit (Kit 5) ----
// L298N channel A: ENA <- D5 (PWM), IN1 <- D4, IN2 <- D7; 12V terminal <- +6V pack, GND <- GND, 5V pin <- Uno 5V (logic)
// L298N channel B: ENB <- D6 (PWM), IN3 <- D12, IN4 <- D13
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define ENA 5
#define IN1 4
#define IN2 7
#define ENB 6
#define IN3 12
#define IN4 13

void motorA(int speed) {                    // -255 .. 255 : sign = direction, 0 = coast
  if (speed > 0) { digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW); }
  else if (speed < 0) { digitalWrite(IN1, LOW); digitalWrite(IN2, HIGH); }
  else { digitalWrite(IN1, LOW); digitalWrite(IN2, LOW); }
  analogWrite(ENA, abs(speed));
}
void driverBegin() {
  pinMode(ENA, OUTPUT); pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT);
  motorA(0);
}
void motorB(int speed) {                    // same for channel B
  if (speed > 0) { digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW); }
  else if (speed < 0) { digitalWrite(IN3, LOW); digitalWrite(IN4, HIGH); }
  else { digitalWrite(IN3, LOW); digitalWrite(IN4, LOW); }
  analogWrite(ENB, abs(speed));
}
void driverBBegin() {
  pinMode(ENB, OUTPUT); pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT);
  motorB(0);
}

void setup() {
  driverBegin();
  driverBBegin();
  Serial.begin(9600);
}

void loop() {
  for (int i = 0; i <= 255; i += 15) {
    motorA(i); motorB(255 - i);
    Serial.print("A "); Serial.print(i); Serial.print("   B "); Serial.println(255 - i);
    delay(150);
  }
  for (int i = 0; i <= 255; i += 15) {
    motorA(255 - i); motorB(-i);                             // B now runs in reverse
    delay(150);
  }
  motorA(0); motorB(0);
  delay(800);
}

// ---- Circuit (Kit 5) ----
// LM35: VCC 5V, GND, OUT -> A0 (10 mV per degree C)
// TIP122: base <- D9 via 1k, emitter -> GND, collector -> motor (low-side switch, 1N4007 flyback diode across the motor)
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define LM35_PIN A0
#define TIP_PIN 9

int level = 0;

float readTemp() {                             // average of 8 readings
  long sum = 0;
  for (int i = 0; i < 8; i++) { sum += analogRead(LM35_PIN); delay(2); }
  return sum / 8.0 * 500.0 / 1023.0;
}

void setup() {
  pinMode(TIP_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float t = readTemp();
  int step = constrain((int)((t - 27.0) / 2.0) + 1, 0, 5);   // 0 = off, 1..5 = five speeds
  int duty = step == 0 ? 0 : 60 + step * 39;
  analogWrite(TIP_PIN, duty);
  if (step != level) {
    level = step;
    Serial.print(t, 1); Serial.print(" C -> step "); Serial.print(step); Serial.print(" of 5, PWM "); Serial.println(duty);
  }
  delay(200);
}

