}

unsigned long lastPrint = 0;

void setup() {
  pinMode(TIP_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float t = readTemp();
  int duty = 0;
  if (t >= 34) duty = 255;
  else if (t >= 31) duty = 180;
  else if (t >= 28) duty = 110;
  analogWrite(TIP_PIN, duty);
  if (millis() - lastPrint > 700) {
    lastPrint = millis();
    Serial.print("temperature "); Serial.print(t, 1); Serial.print(" C   fan PWM "); Serial.println(duty);
  }
  delay(100);
}

// ---- Circuit (Kit 5) ----
// SG90 servo: signal -> D11, red -> 5V, brown -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Green LED anode -> 220 ohm -> A5 (used as a digital pin), cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define SERVO_PIN 11
#define BTN1 2
#define GREEN_LED A5
#define RED_LED 3

#include <Servo.h>
Servo servo;
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

bool open = false;
unsigned long openedAt = 0;

void setGate(bool o) {
  open = o;
  servo.write(o ? 90 : 0);
  digitalWrite(GREEN_LED, o);
  digitalWrite(RED_LED, !o);
  Serial.println(o ? "gate OPEN" : "gate CLOSED");
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  servo.attach(SERVO_PIN);
  Serial.begin(9600);
  setGate(false);
}

void loop() {
  if (pressed()) { if (!open) setGate(true); openedAt = millis(); }     // a press while open restarts the timer
  if (open && millis() - openedAt >= 4000) setGate(false);
}

// ---- Circuit (Kit 5) ----
// ULN2003 stepper board: + -> +6V pack, - -> GND, IN1-IN4 <- A1-A4
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define STEP_IN1 A1
#define STEP_IN2 A2
#define STEP_IN3 A3
#define STEP_IN4 A4

#include <Stepper.h>
Stepper stepper(2048, STEP_IN1, STEP_IN3, STEP_IN2, STEP_IN4);     // 2048 steps per output-shaft revolution (pin order for the 28BYJ-48)

long posSteps = 0;                             // current position in steps (0 = home)
String line = "";

void goToAngle(int deg) {
  long target = deg * 2048L / 360;
  long delta = target - posSteps;
  Serial.print("moving "); Serial.print(delta); Serial.println(" steps");
  stepper.step(delta);
  posSteps = target;
  Serial.print("now at "); Serial.print(deg); Serial.println(" degrees");
}

void setup() {
  stepper.setSpeed(12);
  Serial.begin(9600);
  Serial.println("commands: A<degrees> (absolute angle), H (set home)");
}

void loop() {
  while (Serial.available() > 0) {
    char c = Serial.read();
    if (c == '\n' || c == '\r') {
      if (line.length() > 0) {
        if (line.charAt(0) == 'A' || line.charAt(0) == 'a') goToAngle(line.substring(1).toInt());
        else if (line.charAt(0) == 'H' || line.charAt(0) == 'h') { posSteps = 0; Serial.println("home set"); }
        else Serial.println("unknown command");
      }
      line = "";
    } else line += c;
  }
}

// ---- Circuit (Kit 5) ----
// ULN2003 stepper board: + -> +6V pack, - -> GND, IN1-IN4 <- A1-A4
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define STEP_IN1 A1
#define STEP_IN2 A2
#define STEP_IN3 A3
#define STEP_IN4 A4
#define BTN1 2

#include <Stepper.h>
Stepper stepper(2048, STEP_IN1, STEP_IN3, STEP_IN2, STEP_IN4);     // 2048 steps per output-shaft revolution (pin order for the 28BYJ-48)
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

int dir = 1;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  Serial.begin(9600);
}

void chunk(int rpm) {
  stepper.setSpeed(rpm);
  stepper.step(dir * 40);                    // a short burst of steps at this speed
  if (pressed()) { dir = -dir; Serial.println(dir > 0 ? "direction: clockwise" : "direction: counter-clockwise"); }
}

void loop() {
  Serial.println("accelerating");
  for (int rpm = 2; rpm <= 14; rpm++) { Serial.print("rpm "); Serial.println(rpm); chunk(rpm); chunk(rpm); }
  Serial.println("decelerating");
  for (int rpm = 14; rpm >= 2; rpm--) { chunk(rpm); chunk(rpm); }
}

// ---- Circuit (Kit 5) ----
// Relay module: DC+ 5V, DC- GND, IN <- D8 (active LOW: LOW = relay on)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define RELAY_PIN 8
#define RELAY_ON LOW
#define RELAY_OFF HIGH
#define BTN1 2

int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

#define ON_MS 6000UL
bool lampOn = false;
unsigned long startedAt = 0, lastPrint = 0;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  if (pressed()) {
    startedAt = millis();
    if (!lampOn) { lampOn = true; digitalWrite(RELAY_PIN, RELAY_ON); Serial.println("lamp ON"); }
    else Serial.println("timer restarted");
  }
  if (lampOn) {
    unsigned long left = ON_MS - (millis() - startedAt);
    if (millis() - startedAt >= ON_MS) { lampOn = false; digitalWrite(RELAY_PIN, RELAY_OFF); Serial.println("lamp OFF"); }
    else if (millis() - lastPrint >= 1000) { lastPrint = millis(); Serial.print("off in "); Serial.print(left / 1000 + 1); Serial.println(" s"); }
  }
}

// ---- Circuit (Kit 5) ----
// IRFZ44N: gate <- D10 via 220 ohm, source -> GND, drain -> motor (low-side switch, 1N4007 flyback diode across the motor)
// Supply monitor: 10k + 10k divider from the +6V rail to A0 (A0 reads half of the supply voltage)
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define MOS_PIN 10
#define VSENSE_PIN A0

float supplyVolts() {                       // the 10k + 10k divider halves the voltage
  return analogRead(VSENSE_PIN) * 5.0 / 1023.0 * 2.0;
}

void setup() {
  pinMode(MOS_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  Serial.println("soft start");
  for (int duty = 0; duty <= 255; duty += 5) {
    analogWrite(MOS_PIN, duty);
    if (duty % 50 == 0) { Serial.print("PWM "); Serial.print(duty); Serial.print("   supply "); Serial.print(supplyVolts(), 2); Serial.println(" V"); }
    delay(60);
  }
  Serial.println("full speed");
  delay(2000);
  Serial.println("soft stop");
  for (int duty = 255; duty >= 0; duty -= 5) { analogWrite(MOS_PIN, duty); delay(40); }
  delay(1500);
}

