#define HOLD_MS 3000UL
#define SAFETY_MS 15000UL
int state = 0;                                 // 0 locked, 1 unbolting, 2 opening, 3 open, 4 closing, 5 bolting, 6 fault
int angle = 0;
unsigned long openSince = 0, holdUntil = 0;

void setState(int s, String msg) { state = s; Serial.println(msg); }

void moveDoor(int target) {
  while (angle != target) {
    angle += (target > angle) ? 3 : -3;
    if (abs(angle - target) < 3) angle = target;
    servo.write(angle);
    delay(20);
  }
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(0);
  stepper.setSpeed(14);
  Serial.begin(9600);
  Serial.println("door locked - press the button");
}

void loop() {
  digitalWrite(RED_LED, state == 0 || state == 5 ? HIGH : (state == 6 ? (millis() / 200) % 2 : LOW));
  digitalWrite(GREEN_LED, state == 3);
  if (state == 0 && pressed()) setState(1, "bolt retracting");
  else if (state == 1) { stepper.step(-512); setState(2, "door opening"); }
  else if (state == 2) { moveDoor(90); openSince = millis(); holdUntil = millis() + HOLD_MS; setState(3, "door open"); }
  else if (state == 3) {
    if (pressed()) { holdUntil = millis() + HOLD_MS; Serial.println("hold extended"); }
    if (millis() - openSince > SAFETY_MS) { setState(4, "SAFETY TIMEOUT - forcing the door shut"); openSince = 1; }
    else if (millis() > holdUntil) setState(4, "door closing");
  }
  else if (state == 4) { moveDoor(0); setState(openSince == 1 ? 6 : 5, openSince == 1 ? "FAULT latched - press to clear" : "bolt locking"); }
  else if (state == 5) { stepper.step(512); setState(0, "door locked"); }
  else if (state == 6 && pressed()) { openSince = 0; setState(5, "fault cleared - bolting"); }
}

