#define RUN_MS 3000UL
unsigned long runtimeA = 0, runtimeB = 0;

void runPump(bool a) {
  Serial.print("demand -> pump "); Serial.println(a ? "A (motor)" : "B (relay lamp)");
  if (a) { digitalWrite(TIP_PIN, HIGH); digitalWrite(GREEN_LED, HIGH); }
  else { digitalWrite(RELAY_PIN, RELAY_ON); digitalWrite(RED_LED, HIGH); }
  delay(RUN_MS);
  digitalWrite(TIP_PIN, LOW); digitalWrite(RELAY_PIN, RELAY_OFF);
  digitalWrite(GREEN_LED, LOW); digitalWrite(RED_LED, LOW);
  if (a) runtimeA += RUN_MS / 1000; else runtimeB += RUN_MS / 1000;
  Serial.print("total run time: A "); Serial.print(runtimeA); Serial.print(" s, B "); Serial.print(runtimeB); Serial.println(" s");
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(TIP_PIN, OUTPUT);
