  if (pressed()) runPump(runtimeA <= runtimeB);              // the less-used pump goes first
}

// ---- Circuit (Kit 5) ----
// ULN2003 stepper board: + -> +6V pack, - -> GND, IN1-IN4 <- A1-A4
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Green LED anode -> 220 ohm -> A5 (used as a digital pin), cathode -> GND
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define STEP_IN1 A1
#define STEP_IN2 A2
#define STEP_IN3 A3
#define STEP_IN4 A4
#define BTN1 2
#define GREEN_LED A5

#include <Stepper.h>
Stepper stepper(2048, STEP_IN1, STEP_IN3, STEP_IN2, STEP_IN4);     // 2048 steps per output-shaft revolution (pin order for the 28BYJ-48)
#include <EEPROM.h>

// EEPROM map: 0 = 0xA5 marker, 1..4 = position in steps (32-bit)
long posSteps = 0;

void savePos() {
  EEPROM.write(0, 0xA5);
  for (int i = 0; i < 4; i++) EEPROM.write(1 + i, (posSteps >> (8 * i)) & 255);
}

void loadPos() {
  if (EEPROM.read(0) != 0xA5) { Serial.println("first start - position unknown, assuming home"); posSteps = 0; return; }
  posSteps = 0;
  for (int i = 3; i >= 0; i--) posSteps = (posSteps << 8) | EEPROM.read(1 + i);
  Serial.print("restored position from EEPROM: "); Serial.print(posSteps); Serial.print(" steps ("); Serial.print(posSteps * 360 / 2048); Serial.println(" degrees)");
}

void report() {
  digitalWrite(GREEN_LED, posSteps == 0);
  Serial.print("position "); Serial.print(posSteps); Serial.print(" steps ("); Serial.print(posSteps * 360 / 2048); Serial.println(" degrees)");
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(GREEN_LED, OUTPUT);
  stepper.setSpeed(14);
  Serial.begin(9600);
  loadPos();
  digitalWrite(GREEN_LED, posSteps == 0);
}

void loop() {
  if (digitalRead(BTN1) == LOW) {
    unsigned long t0 = millis();
    while (digitalRead(BTN1) == LOW && millis() - t0 < 1000) { }
    if (digitalRead(BTN1) == LOW) {                          // held: set home
      posSteps = 0; savePos(); report(); Serial.println("home set and saved");
      while (digitalRead(BTN1) == LOW) { }
    } else {                                                 // tapped: move and remember
      stepper.step(256);
      posSteps += 256;
      savePos();
      report();
    }
    delay(40);
  }
}

// ---- Circuit (Kit 5) ----
// Relay module: DC+ 5V, DC- GND, IN <- D8 (active LOW: LOW = relay on)
// TIP122: base <- D9 via 1k, emitter -> GND, collector -> motor (low-side switch, 1N4007 flyback diode across the motor)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define RELAY_PIN 8
#define RELAY_ON LOW
#define RELAY_OFF HIGH
#define TIP_PIN 9
#define BTN1 2
#define RED_LED 3

int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

#define STARTUP_MS 2500UL
#define STALL_MS 1500UL
int state = 0;                                 // 0 idle, 1 running, 2 stalled
unsigned long lastPulse = 0;
int pulses = 0;

void powerOff() {
  digitalWrite(TIP_PIN, LOW);
  delay(100);
  digitalWrite(RELAY_PIN, RELAY_OFF);          // open the supply only after the transistor is off
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(TIP_PIN, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println("press to start, then tap once per revolution");
}

void loop() {
  if (pressed()) {
    if (state == 0) {
      digitalWrite(RELAY_PIN, RELAY_ON); delay(150);
      digitalWrite(TIP_PIN, HIGH);
      state = 1; pulses = 0; lastPulse = millis();
      Serial.println("motor started");
    } else if (state == 1) {
      pulses++; lastPulse = millis();
      Serial.print("revolution "); Serial.println(pulses);
    } else {
      state = 0; digitalWrite(RED_LED, LOW);
      Serial.println("fault cleared - idle");
    }
  }
  if (state == 1) {
    unsigned long limit = (pulses == 0) ? STARTUP_MS : STALL_MS;
    if (millis() - lastPulse > limit) {
      powerOff();
      state = 2;
      digitalWrite(RED_LED, HIGH);
      Serial.println("STALL detected - power cut");
    }
  }
}

// ---- Circuit (Kit 5) ----
// IRFZ44N: gate <- D10 via 220 ohm, source -> GND, drain -> motor (low-side switch, 1N4007 flyback diode across the motor)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define MOS_PIN 10
#define BTN1 2

int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

int mode = 0;
bool level = false;

void announce() {
  if (mode == 0) { analogWrite(MOS_PIN, 128); Serial.println("490 Hz hardware PWM, 50 % duty: smooth running"); }
  if (mode == 1) { analogWrite(MOS_PIN, 0); Serial.println("100 Hz software PWM, 50 %: still smooth, slight hum"); }
  if (mode == 2) { Serial.println("10 Hz software PWM, 50 %: the speed ripples"); }
  if (mode == 3) { Serial.println("2 Hz software PWM, 50 %: the motor starts and stops visibly"); }
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(MOS_PIN, OUTPUT);
  Serial.begin(9600);
  announce();
}

void loop() {
  if (pressed()) {
    mode = (mode + 1) % 4;
    digitalWrite(MOS_PIN, LOW);
    announce();
  }
  if (mode > 0) {
    int halfPeriod = (mode == 1) ? 5 : (mode == 2 ? 50 : 250);        // ms for each half of one PWM period
    level = !level;
    digitalWrite(MOS_PIN, level);
    delay(halfPeriod);
  }
}

