#include <Servo.h>
Servo servo;
void motorA(int speed) {                    // -255 .. 255 : sign = direction, 0 = coast
  if (speed > 0) { digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW); }
  else if (speed < 0) { digitalWrite(IN1, LOW); digitalWrite(IN2, HIGH); }
  else { digitalWrite(IN1, LOW); digitalWrite(IN2, LOW); }
  analogWrite(ENA, abs(speed));
}
void driverBegin() {
  pinMode(ENA, OUTPUT); pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT);
  motorA(0);
}

bool running = false;
int items = 0, diverted = 0;
unsigned long lastItem = 0, divertUntil = 0;

void stopped() { motorA(0); digitalWrite(RED_LED, HIGH); digitalWrite(GREEN_LED, LOW); }

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  driverBegin();
  servo.attach(SERVO_PIN);
  servo.write(90);
  Serial.begin(9600);
  stopped();
  Serial.println("belt stopped - tap = start/stop, hold = jog");
}

void loop() {
  if (digitalRead(BTN1) == LOW) {
    unsigned long t0 = millis();
    while (digitalRead(BTN1) == LOW && millis() - t0 < 700) { }
    if (digitalRead(BTN1) == LOW) {                          // held: jog slowly
      Serial.println("jog");
      motorA(110); digitalWrite(GREEN_LED, HIGH);
      while (digitalRead(BTN1) == LOW) { }
      if (running) motorA(190); else stopped();
    } else {                                                 // tapped: start / stop
      running = !running;
      if (running) { motorA(190); digitalWrite(RED_LED, LOW); digitalWrite(GREEN_LED, HIGH); lastItem = millis(); Serial.println("belt RUNNING"); }
      else { stopped(); Serial.print("belt STOPPED - items "); Serial.print(items); Serial.print(", diverted "); Serial.println(diverted); }
    }
    delay(40);
  }
  if (running && millis() - lastItem >= 2500) {
    lastItem = millis();
    items++;
    Serial.print("item "); Serial.println(items);
    if (items % 3 == 0) { servo.write(30); divertUntil = millis() + 1000; diverted++; Serial.println("diverter: push item off the belt"); }
  }
  if (divertUntil > 0 && millis() > divertUntil) { servo.write(90); divertUntil = 0; }
}

