int profile = 0;

int shape(int p, float t) {                      // t = 0..1 through the run -> PWM 0..255
  if (p == 0) return (int)(255 * t);                                       // linear ramp
  if (p == 1) return (int)(255 * t * t * (3.0 - 2.0 * t));                  // S-curve (smoothstep)
  if (p == 2) return t < 0.33 ? 85 : (t < 0.66 ? 170 : 255);                // three steps
  if (t < 0.25) return (int)(255 * t / 0.25);                              // trapezoid: up, hold, down
  if (t < 0.75) return 255;
  return (int)(255 * (1.0 - t) / 0.25);
}

String name(int p) { if (p == 0) return "LINEAR"; if (p == 1) return "S-CURVE"; if (p == 2) return "STEPS"; return "TRAPEZOID"; }

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  driverBegin(); driverBBegin();
  Serial.begin(9600);
  Serial.println("press the button to run the next profile");
}

void loop() {
  if (pressed()) {
    Serial.print("profile "); Serial.println(name(profile));
    unsigned long t0 = millis();
    unsigned long lastPrint = 0;
    while (millis() - t0 < 4000) {
      float t = (millis() - t0) / 4000.0;
      int pwm = shape(profile, t);
      motorA(pwm); motorB(pwm);
      if (millis() - lastPrint >= 400) { lastPrint = millis(); Serial.print("  t "); Serial.print((millis() - t0) / 100 / 10.0, 1); Serial.print(" s  PWM "); Serial.println(pwm); }
      delay(20);
    }
    motorA(0); motorB(0);
    Serial.println("done");
    profile = (profile + 1) % 4;
  }
}

