String line = "";
int servoAngle = 90, m1 = 0, m2 = 0;
long stepperPos = 0;
bool relayOn = false;

void help() {
  Serial.println("S<0-180>        servo angle        e.g. S90");
  Serial.println("M1 <-255..255>  DC motor           e.g. M1 128");
  Serial.println("M2 <-255..255>  BO motor           e.g. M2 -100");
  Serial.println("T<steps>        stepper steps      e.g. T512");
  Serial.println("R1 on | R1 off  relay lamp");
  Serial.println("STATUS  STOP  HELP");
}

void status() {
  Serial.print("servo "); Serial.print(servoAngle); Serial.print("  M1 "); Serial.print(m1); Serial.print("  M2 "); Serial.print(m2);
  Serial.print("  stepper "); Serial.print(stepperPos); Serial.print(" steps  relay "); Serial.println(relayOn ? "on" : "off");
}

void handle(String c) {
  c.toUpperCase();
  char k = c.charAt(0);
  if (c.startsWith("HELP")) help();
  else if (c.startsWith("STATUS")) status();
  else if (c.startsWith("STOP")) { m1 = 0; m2 = 0; motorA(0); motorB(0); relayOn = false; digitalWrite(RELAY_PIN, RELAY_OFF); Serial.println("all stopped"); }
  else if (c.startsWith("M1")) { m1 = constrain(c.substring(2).toInt(), -255, 255); motorA(m1); Serial.print("M1 = "); Serial.println(m1); }
  else if (c.startsWith("M2")) { m2 = constrain(c.substring(2).toInt(), -255, 255); motorB(m2); Serial.print("M2 = "); Serial.println(m2); }
  else if (c.startsWith("R1")) {
    relayOn = c.indexOf("ON") >= 0;
    digitalWrite(RELAY_PIN, relayOn ? RELAY_ON : RELAY_OFF);
    Serial.println(relayOn ? "relay ON" : "relay OFF");
  }
  else if (k == 'S') { servoAngle = constrain(c.substring(1).toInt(), 0, 180); servo.write(servoAngle); Serial.print("servo = "); Serial.println(servoAngle); }
  else if (k == 'T') { long n = c.substring(1).toInt(); stepper.step(n); stepperPos += n; Serial.print("stepper moved "); Serial.print(n); Serial.println(" steps"); }
  else { Serial.print("unknown command: "); Serial.println(c); }
}

void setup() {
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  driverBegin(); driverBBegin();
  servo.attach(SERVO_PIN);
  servo.write(servoAngle);
  stepper.setSpeed(14);
  Serial.begin(9600);
  Serial.println("motor console ready - type HELP");
}

void loop() {
  while (Serial.available() > 0) {
    char ch = Serial.read();
    if (ch == '\n' || ch == '\r') { if (line.length() > 0) handle(line); line = ""; }
    else line += ch;
  }
}

// ---- Circuit (Kit 5) ----
// Relay module: DC+ 5V, DC- GND, IN <- D8 (active LOW: LOW = relay on)
// SG90 servo: signal -> D11, red -> 5V, brown -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> A5 (used as a digital pin), cathode -> GND
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define RELAY_PIN 8
#define RELAY_ON LOW
#define RELAY_OFF HIGH
#define SERVO_PIN 11
#define BTN1 2
#define RED_LED 3
#define GREEN_LED A5

#include <Servo.h>
Servo servo;

#define CYCLE_MS 4000UL
#define GUARD_OPEN 90
#define GUARD_CLOSED 0
int state = 0;                                  // 0 ready, 1 armed, 2 running, 3 e-stop
unsigned long armedAt = 0, cycleStart = 0;

void show() {
  digitalWrite(GREEN_LED, state == 0);
  digitalWrite(RED_LED, state == 3 ? HIGH : (state == 1 ? (millis() / 200) % 2 : LOW));
}

void estop() {
  digitalWrite(RELAY_PIN, RELAY_OFF);
  state = 3;
  Serial.println("E-STOP: relay off, guard stays closed - hold 2 s to reset");
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(GUARD_OPEN);
  Serial.begin(9600);
  Serial.println("READY - hold the button 1 s, release, then tap within 2 s to start");
}

void loop() {
  if (digitalRead(BTN1) == LOW) {
    if (state == 2) { estop(); while (digitalRead(BTN1) == LOW) { } delay(40); return; }       // any press while running
    unsigned long t0 = millis();
    while (digitalRead(BTN1) == LOW && millis() - t0 < 2000) { }
    unsigned long held = millis() - t0;
    if (held >= 2000) {
      if (state == 3) { state = 0; servo.write(GUARD_OPEN); Serial.println("reset - READY"); }
    } else if (held >= 1000) {
      if (state == 0) { state = 1; armedAt = millis(); Serial.println("ARMED - tap within 2 s"); }
    } else if (state == 1 && millis() - armedAt < 2000) {
      Serial.println("guard closing"); servo.write(GUARD_CLOSED); delay(900);
      digitalWrite(RELAY_PIN, RELAY_ON);
      state = 2; cycleStart = millis();
      Serial.println("CYCLE RUNNING - machine on");
    } else if (state == 0) {
      Serial.println("not armed - hold the button for 1 s first");
    }
    while (digitalRead(BTN1) == LOW) { }
    delay(40);
  }
  if (state == 1 && millis() - armedAt >= 2000) { state = 0; Serial.println("arm timed out"); }
  if (state == 2 && millis() - cycleStart >= CYCLE_MS) {
    digitalWrite(RELAY_PIN, RELAY_OFF);
    delay(300);
    servo.write(GUARD_OPEN);
    state = 0;
    Serial.println("cycle complete - guard open, READY");
  }
  show();
}

// ---- Circuit (Kit 5) ----
// TIP122: base <- D9 via 1k, emitter -> GND, collector -> motor (low-side switch, 1N4007 flyback diode across the motor)
// IRFZ44N: gate <- D10 via 220 ohm, source -> GND, drain -> motor (low-side switch, 1N4007 flyback diode across the motor)
// L293D: pin 16 + EN -> logic 5V, pin 8 -> +6V pack, GND pins -> GND; EN1,2 <- D6 (PWM), 1A <- A1, 2A <- A2
// L298N channel A: ENA <- D5 (PWM), IN1 <- D4, IN2 <- D7; 12V terminal <- +6V pack, GND <- GND, 5V pin <- Uno 5V (logic)
// Motor-node monitor: 10k + 10k divider from the switched (low-side) motor terminal to A0 (A0 reads half of that voltage)
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define TIP_PIN 9
#define MOS_PIN 10
#define L293_EN 6
#define L293_1A A1
#define L293_2A A2
#define ENA 5
#define IN1 4
#define IN2 7
#define VSENSE_PIN A0

float supplyVolts() {                       // the 10k + 10k divider halves the voltage
  return analogRead(VSENSE_PIN) * 5.0 / 1023.0 * 2.0;
}

#define PACK_V 6.0

void drive(int id, bool on) {
  if (id == 0) digitalWrite(TIP_PIN, on);
  if (id == 1) digitalWrite(MOS_PIN, on);
  if (id == 2) { digitalWrite(L293_1A, LOW); digitalWrite(L293_2A, LOW); digitalWrite(L293_EN, on); }   // output 1Y pulls the motor low
  if (id == 3) { digitalWrite(IN1, LOW); digitalWrite(IN2, HIGH); digitalWrite(ENA, on); }               // OUT1 pulls the motor low
}

String name(int id) { if (id == 0) return "TIP122 "; if (id == 1) return "IRFZ44N"; if (id == 2) return "L293D  "; return "L298N  "; }

void setup() {
  pinMode(TIP_PIN, OUTPUT); pinMode(MOS_PIN, OUTPUT);
  pinMode(L293_EN, OUTPUT); pinMode(L293_1A, OUTPUT); pinMode(L293_2A, OUTPUT);
  pinMode(ENA, OUTPUT); pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT);
  for (int i = 0; i < 4; i++) drive(i, false);
  Serial.begin(9600);
  Serial.println("driver benchmark: voltage lost across each switch with the same motor");
}

void loop() {
  float loss[4];
  for (int id = 0; id < 4; id++) {
    drive(id, true);
    delay(1100);
    float sum = 0;
    for (int i = 0; i < 20; i++) { sum += supplyVolts(); delay(10); }
    drive(id, false);
    loss[id] = sum / 20;
    Serial.print(name(id)); Serial.print(": "); Serial.print(loss[id], 2); Serial.print(" V lost, motor gets about "); Serial.print(PACK_V - loss[id], 2); Serial.println(" V");
    delay(700);
  }
  int best = 0;
  for (int i = 1; i < 4; i++) if (loss[i] < loss[best]) best = i;
  Serial.print("most efficient: "); Serial.println(name(best));
  Serial.println("----");
  delay(2500);
}

// ---- Circuit (Kit 5) ----
// ULN2003 stepper board: + -> +6V pack, - -> GND, IN1-IN4 <- A1-A4
// SG90 servo: signal -> D11, red -> 5V, brown -> GND
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Green LED anode -> 220 ohm -> A5 (used as a digital pin), cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// 4xAA pack (6 V): + -> bottom red rail (+6V), - -> bottom blue rail (GND), joined to the Uno GND
#define STEP_IN1 A1
#define STEP_IN2 A2
#define STEP_IN3 A3
#define STEP_IN4 A4
#define SERVO_PIN 11
#define BTN1 2
#define GREEN_LED A5
#define RED_LED 3

#include <Servo.h>
Servo servo;
#include <Stepper.h>
Stepper stepper(2048, STEP_IN1, STEP_IN3, STEP_IN2, STEP_IN4);     // 2048 steps per output-shaft revolution (pin order for the 28BYJ-48)
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

long basePos = 0;
int armAngle = 90, axis = 0, jogDir = 1, taps = 0, n = 0;
long wpBase[6];
int wpArm[6];
bool replay = false;
unsigned long lastTap = 0;

void saveWaypoint() {
  if (n >= 6) { Serial.println("memory full (6 waypoints)"); return; }
  wpBase[n] = basePos; wpArm[n] = armAngle; n++;
  Serial.print("saved waypoint "); Serial.print(n); Serial.print(": base "); Serial.print(basePos); Serial.print(" steps, arm "); Serial.println(armAngle);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(armAngle);
  stepper.setSpeed(14);
  Serial.begin(9600);
  digitalWrite(RED_LED, HIGH);
  Serial.println("recording - hold = jog, tap x1 save, x2 switch axis, x3 replay");
}

void jog() {
  Serial.print("jogging "); Serial.println(axis == 0 ? "base" : "arm");
  while (digitalRead(BTN1) == LOW) {
    if (axis == 0) { stepper.step(jogDir * 24); basePos += jogDir * 24; }
    else { armAngle = constrain(armAngle + jogDir, 0, 180); servo.write(armAngle); delay(12); }
  }
  jogDir = -jogDir;
}

void loop() {
  if (!replay) {
    if (digitalRead(BTN1) == LOW) {
      unsigned long t0 = millis();
      while (digitalRead(BTN1) == LOW && millis() - t0 < 400) { }
      if (digitalRead(BTN1) == LOW) jog();
      else { taps++; lastTap = millis(); }
      delay(40);
    }
    if (taps > 0 && millis() - lastTap > 600) {
      if (taps == 1) saveWaypoint();
      else if (taps == 2) { axis = 1 - axis; Serial.print("axis: "); Serial.println(axis == 0 ? "base (stepper)" : "arm (servo)"); }
      else if (n > 0) { replay = true; digitalWrite(RED_LED, LOW); digitalWrite(GREEN_LED, HIGH); Serial.println("REPLAY"); }
      taps = 0;
    }
  } else {
    for (int i = 0; i < n && replay; i++) {
      Serial.print("-> waypoint "); Serial.println(i + 1);
      stepper.step(wpBase[i] - basePos); basePos = wpBase[i];
      servo.write(wpArm[i]); armAngle = wpArm[i];
      unsigned long t0 = millis();
      while (millis() - t0 < 700) { if (digitalRead(BTN1) == LOW) { replay = false; break; } }
      if (digitalRead(BTN1) == LOW) replay = false;
    }
    if (!replay) {
      digitalWrite(GREEN_LED, LOW); digitalWrite(RED_LED, HIGH);
      Serial.println("replay stopped - recording");
      while (digitalRead(BTN1) == LOW) { }
      delay(60);
    }
  }
}
